// Skin runtime parity probe — replays the TS-generated golden-skin.json scene
// corpus through the pure C# skin port and compares the resolved scene trees
// node by node (structure exact; numbers with tolerance; colors exact strings).
//
//   dotnet run --project Tools/SkinProbe [--full]
//
// golden-skin.json is generated by Tools/SkinProbe/golden-skin.ts (see its
// header). --full prints every mismatch instead of the first 40.

using System.Globalization;
using Newtonsoft.Json.Linq;

const double RelTolerance = 1e-9;
const double AbsTolerance = 1e-12;
var maxPrinted = args.Contains("--full") ? int.MaxValue : 40;

// ------------------------------------------------------------------ compile
var document = SkinJson.Parse(File.ReadAllText("Assets/StreamingAssets/Skins/flat.skin.json"));
var skin = SkinCompiler.Compile(document);
Console.WriteLine($"compiled skin '{skin.Id}' — animations {skin.Animations.Count}, slots {skin.Slots.Count}, " +
                  $"color refs {skin.ColorRefs.Count}");

// ------------------------------------------------------------------ contexts
// Palette constants mirror DefaultSkinPalettes: the skin meta palette section
// is no longer consumed anywhere (the game derives palettes from game config).
const double chroma = 0.165;

FlatFamily FamilyFor(NoteKind kind) => kind switch
{
    NoteKind.Click => FlatFamily.Click,
    NoteKind.Hold => FlatFamily.Hold,
    NoteKind.LongHold => FlatFamily.LongHold,
    NoteKind.DragHead or NoteKind.DragChild => FlatFamily.Drag,
    NoteKind.Flick => FlatFamily.Flick,
    NoteKind.ClickDragHead => FlatFamily.Click, // FAMILY_OF: the cdrag head is a click note
    NoteKind.ClickDragChild => FlatFamily.ClickDrag,
    NoteKind.DropClick => FlatFamily.DropClick,
    NoteKind.DropDrag => FlatFamily.DropDrag,
    _ => throw new ArgumentOutOfRangeException(nameof(kind)),
};

double HueFor(FlatFamily family, FlatDirection direction) => DefaultSkinPalettes.Hue(family, direction);

SkinNotePalette NotePaletteFor(NoteKind kind, FlatDirection direction, string seed)
{
    var family = FamilyFor(kind);
    var hue = HueFor(family, direction);
    if (seed == null || seed == "default")
        return DefaultSkinPalettes.Family(family, direction);
    if (seed.StartsWith("ring:"))
        return SkinPalette.FromHue(hue, new SkinPalette.Options { Chroma = chroma, Ring = seed.Substring(5) });
    return SkinPalette.FromHex(seed.Substring(1), new SkinPalette.Options { Chroma = chroma });
}

var gradePalettes = new SkinGradePalettes(DefaultSkinPalettes.GradeColors);

double SizeOf(NoteKind kind) => kind switch
{
    NoteKind.DragHead => 0.675,
    NoteKind.DragChild or NoteKind.ClickDragChild => 0.375,
    NoteKind.Flick => 1.125,
    NoteKind.DropDrag => 0.8,
    _ => 1,
};

NoteKind KindOf(string slot)
{
    var kindKey = slot.Split(':')[0];
    foreach (var kind in SkinTimingTokens.NoteKinds)
    {
        if (SkinTimingTokens.KindKey(kind) == kindKey) return kind;
    }
    throw new ArgumentException($"unknown kind in slot '{slot}'");
}

SkinDrawContext MakeContext(string slot, JObject ctxTag)
{
    var kind = KindOf(slot);
    var direction = (string) ctxTag["direction"] == "down" ? FlatDirection.Down : FlatDirection.Up;
    var bodyDirection = (string) ctxTag["bodyDirection"] == "down" ? FlatDirection.Down : FlatDirection.Up;
    var seed = (string) ctxTag["seed"] ?? "default";
    return new SkinDrawContext
    {
        Kind = kind,
        RingStroke = 128 * 0.085,
        HairStroke = 128 * 0.022,
        Palettes = new SkinPaletteContext
        {
            Note = NotePaletteFor(kind, direction, seed),
            Grades = gradePalettes,
            Family = (family, direction) => DefaultSkinPalettes.Family(family, direction),
        },
        Direction = direction,
        BodyDirection = bodyDirection,
        Heading = (double) ctxTag["heading"],
        Approach = (double) ctxTag["approach"],
        Size = 128 * SizeOf(kind),
        Unit = 128,
    };
}

// ------------------------------------------------------------------ replay
var painter = new SkinPainter();
var sinks = new SkinSinks(new FlatMeshBuilder());

JObject DumpScene(JObject scene)
{
    var slotKey = (string) scene["slot"];
    var ctx = MakeContext(slotKey, (JObject) scene["ctx"]);
    var slot = skin.Slots[slotKey];
    painter.BeginDump(skin);
    if (slot.Contract.Path == "chainLink" && slot.Contract.Kind != null)
    {
        painter.DrawChainLinkSlot(slot, ChainOptionsOf((JObject) scene["options"]), ctx, sinks);
    }
    else if (slot.Contract.Path == "body" && slot.Contract.Kind != null)
    {
        painter.DrawBodySlot(slot, BodyOptionsOf((JObject) scene["options"]), ctx, sinks);
    }
    else if (slot.Contract.View != null)
    {
        painter.DrawFeedbackSlot(slot, (double) scene["x"], ctx, sinks);
    }
    else
    {
        painter.DrawNoteSlot(slot, (double) scene["x"], ctx, sinks);
    }
    return painter.EndDump();
}

SkinInputs.ChainOptions ChainOptionsOf(JObject options)
{
    var chain = new SkinInputs.ChainOptions();
    if (options.TryGetValue("length", out var length)) chain.Length = (double) length;
    if (options.TryGetValue("t", out var t)) chain.T = (double) t;
    return chain;
}

SkinInputs.BodyOptions BodyOptionsOf(JObject options)
{
    var body = new SkinInputs.BodyOptions();
    if (options.TryGetValue("length", out var length)) body.Length = (double) length;
    if (options.TryGetValue("top", out var top)) body.Top = (double) top;
    if (options.TryGetValue("bottom", out var bottom)) body.Bottom = (double) bottom;
    if (options.TryGetValue("progress", out var progress)) body.Progress = (double) progress;
    if (options.TryGetValue("t", out var t)) body.T = (double) t;
    if (options.TryGetValue("holdDuration", out var hold)) body.HoldDuration = (double) hold;
    if (options.TryGetValue("appear", out var appear)) body.Appear = (double) appear;
    return body;
}

// ------------------------------------------------------------------ compare
var diffs = new List<string>();
var sceneCount = 0;
var pass = 0;
var fail = 0;

void CompareScene(JObject scene)
{
    if (scene.TryGetValue("error", out _)) return;
    sceneCount++;
    var golden = scene["root"];
    JObject actual;
    try
    {
        actual = DumpScene(scene);
    }
    catch (Exception e)
    {
        fail++;
        diffs.Add($"{scene["slot"]} x={FormatX(scene)} → C# threw: {e.Message}");
        return;
    }
    CompareNode(golden, actual == null ? JValue.CreateNull() : actual, "root", scene);
}

void CompareNode(JToken golden, JToken actual, string path, JObject scene)
{
    if (golden is JValue { Type: JTokenType.Null })
    {
        if (actual is JValue { Type: JTokenType.Null }) return;
        fail++;
        diffs.Add($"{scene["slot"]} x={FormatX(scene)} {path}: golden null, C# {actual.Type}");
        return;
    }
    switch (golden)
    {
        case JObject goldenObject:
        {
            if (actual is not JObject actualObject)
            {
                fail++;
                diffs.Add($"{scene["slot"]} x={FormatX(scene)} {path}: golden object, C# {actual.Type}");
                return;
            }
            foreach (var property in goldenObject.Properties())
            {
                if (!actualObject.TryGetValue(property.Name, out var actualChild))
                {
                    fail++;
                    diffs.Add($"{scene["slot"]} x={FormatX(scene)} {path}.{property.Name}: missing in C# (golden {Describe(property.Value)})");
                    continue;
                }
                CompareNode(property.Value, actualChild, $"{path}.{property.Name}", scene);
            }
            foreach (var property in actualObject.Properties())
            {
                if (property.Name != "t" && !goldenObject.ContainsKey(property.Name))
                {
                    fail++;
                    diffs.Add($"{scene["slot"]} x={FormatX(scene)} {path}.{property.Name}: extra in C# ({Describe(property.Value)})");
                }
            }
            return;
        }
        case JArray goldenArray:
        {
            if (actual is not JArray actualArray || actualArray.Count != goldenArray.Count)
            {
                fail++;
                diffs.Add($"{scene["slot"]} x={FormatX(scene)} {path}: golden {goldenArray.Count} items, C# {actual.Type}");
                return;
            }
            for (var i = 0; i < goldenArray.Count; i++)
                CompareNode(goldenArray[i], actualArray[i], $"{path}[{i}]", scene);
            return;
        }
        case JValue goldenNumber when goldenNumber.Type is JTokenType.Float or JTokenType.Integer:
        {
            if (actual is not JValue { Type: JTokenType.Float or JTokenType.Integer })
            {
                fail++;
                diffs.Add($"{scene["slot"]} x={FormatX(scene)} {path}: golden {goldenNumber}, C# {actual}");
                return;
            }
            var expected = (double) goldenNumber;
            var value = (double) actual;
            var scale = Math.Max(1.0, Math.Abs(expected));
            if (Math.Abs(value - expected) <= Math.Max(AbsTolerance, RelTolerance * scale))
            {
                pass++;
                return;
            }
            fail++;
            diffs.Add($"{scene["slot"]} x={FormatX(scene)} {path}: golden {FormatNumber(expected)}, C# {FormatNumber(value)}");
            return;
        }
        case JValue goldenToken:
        {
            if (actual is JValue actualToken && Equals(goldenToken.Value, actualToken.Value))
            {
                pass++;
                return;
            }
            fail++;
            var actualText = actual is JValue v ? v.Value?.ToString() : actual.Type.ToString();
            diffs.Add($"{scene["slot"]} x={FormatX(scene)} {path}: golden {goldenToken.Value}, C# {actualText}");
            return;
        }
    }
}

static string Describe(JToken token) => token.Type == JTokenType.String ? $"\"{token}\"" : token.ToString(Newtonsoft.Json.Formatting.None);

static string FormatX(JObject scene) => scene.TryGetValue("x", out var x) ? FormatNumber((double) x) : "-";

static string FormatNumber(double v) => v.ToString("R", CultureInfo.InvariantCulture);

// ------------------------------------------------------------------ run
var goldenPath = "Tools/SkinProbe/golden-skin.json";
if (!File.Exists(goldenPath))
{
    Console.Error.WriteLine($"missing {goldenPath} — regenerate with Tools/SkinProbe/golden-skin.ts");
    return 1;
}
var corpus = JObject.Parse(File.ReadAllText(goldenPath));
foreach (var scene in (JArray) corpus["scenes"])
{
    var slot = (string) scene["slot"];
    if (skin.Slots.ContainsKey(slot)) CompareScene((JObject) scene);
}

Console.WriteLine($"scenes replayed: {sceneCount}");
Console.WriteLine($"value comparisons passed: {pass}, failed: {fail}");
var printed = 0;
foreach (var diff in diffs)
{
    if (printed++ >= maxPrinted)
    {
        Console.WriteLine($"… {diffs.Count - printed + 1} more (use --full)");
        break;
    }
    Console.WriteLine(diff);
}
// ------------------------------------------------------------------ draw pass
// Every scene through the real tessellation path (FlatGeom into a builder) —
// catches paint-only crashes and NaN geometry, and measures steady-state GC.
long drawVerts = 0;
var drawFailures = new List<string>();
var drawBuilder = new FlatMeshBuilder();
var drawSinks = new SkinSinks(drawBuilder);
var unsupportedSlots = new SortedSet<string>();

// Every scene through the real tessellation path (FlatGeom into a builder) —
// catches paint-only crashes and NaN geometry, and measures steady-state GC.
// Contexts and body options are prebuilt so the measurement isolates the painter itself.
var sceneList = ((JArray) corpus["scenes"]).Cast<JObject>().Where(s => skin.Slots.ContainsKey((string) s["slot"])).ToList();
var sceneContexts = sceneList.Select(s => MakeContext((string) s["slot"], (JObject) s["ctx"])).ToList();
var sceneBodies = sceneList
    .Select(s => s.TryGetValue("options", out var options) && options is JObject body ? BodyOptionsOf(body) : null)
    .ToList();
var sceneChains = sceneList
    .Select(s => s.TryGetValue("options", out var options) && options is JObject chain ? ChainOptionsOf(chain) : null)
    .ToList();

foreach (var scene in sceneList)
{
    var slot = skin.Slots[(string) scene["slot"]];
    if (!slot.UsesUnsupported) continue;
    var why = (slot.Animation.UsesImages ? "images " : "") + (slot.Animation.UsesClip ? "clip " : "") +
              (slot.Animation.UsesCurvedDash ? "curved-dash" : "");
    unsupportedSlots.Add($"{(string) scene["slot"]} ({why.Trim()})");
}

// Warm-up (pool growth, palette caches), then measure managed allocation of a full replay.

void DrawScene(JObject scene, SkinDrawContext ctx, SkinInputs.BodyOptions body, SkinInputs.ChainOptions chain)
{
    var slotKey = (string) scene["slot"];
    var slot = skin.Slots[slotKey];
    try
    {
        drawBuilder.Reset();
        if (slot.Contract.Path == "chainLink" && slot.Contract.Kind != null)
            painter.DrawChainLinkSlot(slot, chain, ctx, drawSinks);
        else if (slot.Contract.Path == "body" && slot.Contract.Kind != null)
            painter.DrawBodySlot(slot, body, ctx, drawSinks);
        else if (slot.Contract.View != null)
            painter.DrawFeedbackSlot(slot, (double) scene["x"], ctx, drawSinks);
        else
            painter.DrawNoteSlot(slot, (double) scene["x"], ctx, drawSinks);
        drawVerts += drawBuilder.VertCount;
        for (var i = 0; i < drawBuilder.Verts.Count; i++)
        {
            if (float.IsNaN(drawBuilder.Verts[i]) || float.IsInfinity(drawBuilder.Verts[i]))
            {
                drawFailures.Add($"{slotKey} x={FormatX(scene)}: NaN/Inf vertex at {i}");
                break;
            }
        }
    }
    catch (Exception e)
    {
        drawFailures.Add($"{slotKey} x={FormatX(scene)} → {e.Message}");
    }
}

for (var i = 0; i < sceneList.Count; i++) DrawScene(sceneList[i], sceneContexts[i], sceneBodies[i], sceneChains[i]);
drawVerts = 0;
var gcBefore = GC.GetAllocatedBytesForCurrentThread();
var drawStart = DateTime.UtcNow;
for (var i = 0; i < sceneList.Count; i++) DrawScene(sceneList[i], sceneContexts[i], sceneBodies[i], sceneChains[i]);
var drawMillis = (DateTime.UtcNow - drawStart).TotalMilliseconds;
var gcBytes = GC.GetAllocatedBytesForCurrentThread() - gcBefore;

// Per-slot allocation breakdown (after warm-up) to localize any leak.
var perSlot = new SortedList<string, long>();
var perSlotCounts = new SortedList<string, int>();
for (var i = 0; i < sceneList.Count; i++)
{
    var key = (string) sceneList[i]["slot"];
    var before = GC.GetAllocatedBytesForCurrentThread();
    DrawScene(sceneList[i], sceneContexts[i], sceneBodies[i], sceneChains[i]);
    var delta = GC.GetAllocatedBytesForCurrentThread() - before;
    perSlot[key] = (perSlot.TryGetValue(key, out var sum) ? sum : 0) + delta;
    perSlotCounts[key] = (perSlotCounts.TryGetValue(key, out var count) ? count : 0) + 1;
}

var topAllocators = perSlot.OrderByDescending(p => p.Value).Take(8).ToList();
if (topAllocators.Count > 0 && topAllocators[0].Value > 0)
{
    Console.WriteLine("top allocating slots:");
    foreach (var entry in topAllocators)
        Console.WriteLine($"  {entry.Key}: {entry.Value / (double) perSlotCounts[entry.Key]:F1} B/scene");
}

Console.WriteLine($"draw pass: {drawVerts} vertices, {drawMillis:F0} ms, " +
                  $"steady-state allocation {gcBytes / 1024.0:F1} KB ({gcBytes / (double) ((JArray) corpus["scenes"]).Count:F1} B/scene)");
if (unsupportedSlots.Count > 0)
    Console.WriteLine("capability-flagged slots (heads/bodies skip drawing in-game): " + string.Join(", ", unsupportedSlots));
foreach (var failure in drawFailures.Take(20)) Console.WriteLine("DRAW FAIL " + failure);
if (drawFailures.Count > 20) Console.WriteLine($"… {drawFailures.Count - 20} more draw failures");

return fail == 0 && drawFailures.Count == 0 ? 0 : 2;
